#!/usr/bin/env python3
"""Authored after reading source execution bodies, native headers/bodies and command fixtures."""
from pathlib import Path
import os,re
BASE=Path(__file__).resolve().parents[1];CPP=BASE.parent

def update(rel,purpose,steps,adaptation,tests,exercise,limits=''):
 p=BASE/'files/src/org/minima/system/commands'/rel;s=p.read_text()
 def link(path,label):return f'[{label}]({os.path.relpath(path,p.parent)})'
 def section(title,body):
  nonlocal s
  s=re.sub(r'(## '+re.escape(title)+r'\n\n).*?(?=\n## |\Z)',lambda m:m[1]+body+'\n',s,flags=re.S)
 s=re.sub(r'\*\*Teaching status:\*\*[^\n]+','**Teaching status:** Authored algorithm and test explanation; full API/parity review remains open.',s)
 s=s.replace('— source reading notes','— command lesson')
 section('What this file does',purpose)
 section('Follow the logic','\n'.join(f'{i}. {t}' for i,t in enumerate(steps,1)))
 section('How the translation is approached',adaptation)
 section('What the tests tell us',tests+'\n\nThe actual '+link(CPP/'tools/command_differential.py','command driver')+' creates the inputs; '+link(CPP/'support/CommandOracle.java','CommandOracle.java')+' runs the pinned Java commands and '+link(CPP/'support/command.cpp','command.cpp')+' runs the native commands. The oracle uses a synthetic wallet address cache, not durable wallet storage. CommandException messages are compared separately, while other exceptions become ERROR. The existing '+link(CPP/'build/command-differential-results.json','normal report')+' records 12,289 cases passed, zero failures. This is a snapshot of the whole suite, not a new run or this command’s dedicated case count. Random outputs use per-runtime property checks rather than equality between independently generated bytes.')
 section('Check your understanding',exercise)
 sourcehash=s[s.index('Pinned Java SHA-256:'):].strip()
 section('Limits and traceability','The explanation covers the inspected execution path and stated tests. Full API, generic exception, concurrency and node integration parity remain open. '+limits+'\n\n'+sourcehash)
 p.write_text(s)

update('Command.md','Supply the shared parameter rules and JSON response envelope used by commands.',
 ['Store command/help text and an initially empty shared parameter object. Complete-command and MiniDapp ID metadata are independent fields.','getParam distinguishes a missing key from a present value. Present values must be strings, are trimmed and must not be blank. A default applies only when the key is absent; it does not repair a null or invalid present value.','Boolean access accepts only the exact trimmed string true. Number access delegates to MiniNumber. Data access converts Mx or HEX and wraps conversion failures as a CommandException. Address access has different source catch/normalization rules and permits some plain text to pass to its caller.','JSON object/array access returns the existing object reference, including null where the source cast permits it. Type predicates test the actual stored object type.','getJSONReply returns command, status=true and pending=false. It includes the actual parameter object only when nonempty, so later parameter mutation can remain visible through a prior reply.'],
 'C++ uses an ordered shared JSONObject for parameters, optional strings/values for nullable defaults and explicit overloads for null defaults. Existing MiniNumber, Address and JSON code supply conversions. UTF-16 accessor variants preserve selected Java string errors, while some older narrow accessors still normalize generic errors differently.',
 'The driver crosses absent/present keys with null, empty/blank strings, booleans, numbers, arrays, objects, Unicode, malformed Mx/HEX and numerical extremes. It tests null defaults separately. reply obtains a response then mutates parameters; alias obtains a nested object then changes it, directly checking shared-reference behavior.',
 'Why must getParam("x", "default") fail for a present blank x rather than returning the default?')
update('CommandException.md','Distinguish a command-level error from a generic runtime failure.',
 ['Receive an error message and pass it unchanged to the superclass.','Let command/runner catch sites decide how to display it. This class itself performs no logging, retry or response construction.'],
 'The native class derives from std::runtime_error and retains the supplied message. The command harness catches it before std::exception and renders COMMAND_ERROR:<message>. Java’s checked-exception compilation rule has no direct C++ equivalent.',
 'Missing/blank required parameters, invalid conversion kinds and wrong signature public keys produce command-specific failures. The separate CommandException catch means a port that throws only generic errors will disagree even when both reject the request.',
 'Why does preserving the exception family matter when the final user sees JSON rather than an exception object?')
update('base/hash.md','Hash an input value or the contents of a file.',
 ['If file is present, resolve it and reject a nonexistent path before reading bytes. This branch takes priority over data.','Otherwise stringify a JSON object/array directly or read the string parameter. Only a lowercase 0x prefix selects raw HEX; other text is encoded with MiniString.','Read type with default sha3, then select SHA2 or SHA3 exactly; reject other spellings.','Return file name/path/size or input/decoded bytes, followed by type and hash.'],
 'C++ reuses MiniFile, MiniString, MiniData and Crypto. It follows the same file priority and input interpretation. Filesystem error details and time-of-check/file-size races remain beyond the finite fixture.',
 'The driver tests objects, arrays, Unicode text, 0x versus 0X, invalid hash kinds, files of 0/1/256/65536 bytes, a directory and an absent path. File cases include data:"ignored" to exercise precedence.',
 'Why do hash data:0x4142 and hash data:0X4142 hash different inputs?')
update('base/missingcmd.md','Construct a structured error response for a command that could not be dispatched.',
 ['Retain the original input and error at construction.','Obtain the common reply, replace command with the original input, set status=false and add error.','A new function instance resets its input and error to empty strings.'],
 'C++ uses optional strings to preserve null input/error instead of converting them into empty strings. It reuses Command’s parameter-envelope behavior.',
 'The driver combines null, empty, ordinary and Unicode input strings with null/empty/explanatory errors, and supplies parameters to ensure the shared envelope remains present.',
 'What is the difference between a null error value and an absent error field in the returned JSON?')
update('base/convert.md','Convert bytes between HEX, Minima address text, string encoding and Base64.',
 ['Read and lowercase from/to, then obtain data as stringified JSON or a string parameter. These operations occur before the conversion try block.','Decode the selected input format into one MiniData value. Reject an unknown FROM kind.','Encode those same bytes into the requested output format; reject an unknown TO kind.','Rethrow CommandException unchanged and wrap other caught conversion exceptions with their source-style text. Return response.conversion.'],
 'C++ reuses MiniData, Address, MiniString and the existing Base64 helpers. Java-style case conversion is reused. Keeping decode and encode around a byte value avoids lossy text conversions for arbitrary binary input.',
 'The driver crosses formats and malformed values, enumerates short Base64 strings over an alphabet containing padding, invalid punctuation and non-ASCII text, and round-trips deterministic arbitrary bytes. It also tests missing parameters and case/space variations of kind names.',
 'Why should converting HEX to Base64 avoid an intermediate UTF-8 string?')
update('base/random.md','Generate random bytes, hash them and optionally derive a display key code.',
 ['Read size as MiniNumber with default32, convert it to a Java-style int and request that many random bytes. This happens before hash-type validation.','Select exact sha2/sha3 with default sha3 and hash the generated bytes.','Return the original size text, random HEX, digest and type. For an integer byte count at least16, Base32-encode the random bytes and take five four-character groups at source-defined offsets.'],
 'C++ reuses OS-random MiniData and Crypto, with an explicit negative-array-size error. The key-code substring indices are preserved, including gaps between groups; a normal grouped Base32 formatter would not be equivalent.',
 'Deterministic failure/zero-size cases compare Java and C++ output. Nonempty random cases instead verify each runtime’s byte length, hash digest and exact Base32 substring construction. Fractional and wrapping size inputs distinguish displayed MiniNumber size from allocated int count.',
 'Why is requiring Java and C++ to generate identical random bytes the wrong test here?',
 'These properties do not measure entropy quality or establish equivalence of random-provider failure behavior.')
update('base/checkaddress.md','Validate an address format and report its wallet relevance flags.',
 ['Normalize the address through Command.getAddressParam.','If it starts with0x, require66 characters; then require a0x or Mx prefix.','Obtain the wallet, parse bytes and create both HEX and displayed Minima forms.','Return normalized original,0x,Mx,relevant and simple fields using wallet lookups.'],
 'C++ invokes the required ChainServices address-relevance/simple callbacks after validation. Those callbacks are a runtime boundary, not a native persistent wallet implementation.',
 'The Java fixture injects tracked/simple address sets with known overlapping membership. Native callbacks implement the corresponding controlled sets. The driver checks those four combinations in HEX/Mx form, malformed lengths, invalid prefixes and missing input.',
 'Why does a valid address not necessarily belong to this wallet? Separate syntax from the two cache lookups.')
update('base/debugflag.md','Update the global debug flag and optionally its accompanying string.',
 ['Read activate with default false. Set DEBUGFLAG true only for exact true; every other accepted string sets it false.','Only if var is present, read it and update DEBUGVAR. If this read fails, the flag assignment has already happened.','Return the current flag and variable. Omitting var preserves its prior value, while omitting activate resets the flag false.'],
 'C++ writes the existing GeneralParams fields directly and preserves assignment order.',
 'The driver varies activate and var across correct strings, null, wrong JSON types and blanks, then issues follow-up calls in the same process. A dedicated sequence checks retained DEBUGVAR and failed updates.',
 'After activate:true var:<invalid>, can a later call observe a changed flag even though the first command failed?')
update('base/maths.md','Evaluate text using the actual KISS arithmetic and return the variable returnvalue.',
 ['Read calculate and the optional exact-string logs Boolean.','Construct the script LET returnvalue = followed by the supplied text, using a Contract with empty transaction/witness context and source-selected cleaning mode.','Run the Contract, then read returnvalue and call toString. The command does not first inspect parse/success flags.','Return the result and optionally the complete trace.'],
 'C++ reuses Contract and the VM’s MiniNumber arithmetic. Its explicit missing-returnvalue check represents the Java dereference failure, with generic diagnostics normalized by this suite.',
 'The driver tests precedence, SIGDIG, strings/booleans/HEX, division by zero, negative square root, globals, malformed input and text containing an additional LET/RETURN. This demonstrates that the source constructs a script rather than using a separate calculator grammar.',
 'Why might calculate:"1 LET x = 1/0" still leave a returnvalue even though a later statement fails?')
update('base/mmrcreate.md','Create an MMR from supplied data-and-sum strings and return a proof for every leaf.',
 ['Require a JSON array and cast each element to string. Split at the first colon; default sum to zero when absent.','Build a leaf from MiniData for lowercase0x input or MiniString otherwise, then append it to the real MMR and retain its input/index.','After all inserts, get the root and construct each leaf’s serialized MMR proof.','Return nodes, total and root. An empty tree has no root; dereferencing it fails rather than returning a fabricated empty commitment.'],
 'C++ reuses MMR, MMRData and MMRProof. A small record retains source input/index/sum for the response; null roots are explicitly rejected. No parallel proof algorithm is introduced.',
 'The driver builds trees around power-of-two boundaries from1 through65 leaves, with HEX/text and several sums. It feeds Java-produced proofs into mmrproof. Invalid arrays, null/nonnumeric elements, bad HEX and extra colons exercise decoding failures.',
 'Why are tree sizes7,8 and9 more revealing than testing only a perfectly balanced8-leaf tree?')
update('base/mmrproof.md','Reconstruct an MMR root from a supplied leaf and proof, then compare hash and sum.',
 ['First require the presence of root, proof and data together.','Read data and root, split optional colon sums and trim the split components; sums default to zero.','Build a typed leaf, decode the serialized proof and fold it with calculateProof.','Return the input, leaf, calculated final data and a Boolean equality against the expected root.'],
 'C++ delegates leaf/proof operations to existing MMR classes and mirrors split/trim behavior. The command’s unused nested record remains represented in the header; it is not part of this execution path.',
 'Using actual mmrcreate results, the driver checks valid leaves/proofs and independently changes data, root sums and proof bytes; it adds truncation, trailing bytes, spaces and a root without an explicit sum. This distinguishes proof folding from mere parse success.',
 'Can a proof parse successfully but yield valid:false? Identify one mutation that should do so.')
update('scripts/runscript.md','Build a supplied test context, execute a KISS script and report its addresses and execution state.',
 ['Read script plus optional state, previous state, globals, signature-key list and extra scripts. Build a transaction/witness by converting state ports, values, keys and serialized script proofs in source order.','Construct Contract and set @SCRIPT. If the original globals object contains uppercase @BLOCK and @CREATED but not @COINAGE, compute and insert their difference into that same globals object.','Uppercase global names when installing their Values, then run Contract. Later supplied globals can overwrite @SCRIPT.','Return original and cleaned script/address pairs, trace, variables and parse/monotonic/success flags.'],
 'C++ reuses JSON, JavaInteger parsing, StateVariable, ScriptProof and Contract. Shared globals retain the visible @COINAGE mutation. Some context null checks and accessor ordering differ from Java, so the current normalized suite cannot certify every partial failure effect.',
 'The driver supplies valid/invalid scripts, matching/differing state, explicit and derived globals, key lists and MAST proofs generated by mmrcreate. It varies context JSON types and Unicode/overflow port strings and tests uppercase versus lowercase globals.',
 'Why can lowercase @block and @created be installed as globals yet fail to trigger automatic @COINAGE insertion?')
update('signatures/verify.md','Verify signed data with an explicitly supplied public key.',
 ['Read data, public key and serialized signature in that order through Command’s data conversion.','Decode Signature and obtain its root public key. Reject a mismatch with the supplied key before cryptographic verification.','Configure TreeKey with the signature root and verify the data.','For invalid cryptography, return status=false with a message; for valid cryptography, return response:"Signature valid". A key mismatch instead throws CommandException.'],
 'C++ reuses Signature and TreeKey. It explicitly rejects a missing decoded signature, with that generic error normalized in this suite. The distinct mismatch/error/invalid-result channels remain significant.',
 'Java generates real signatures at key-use positions0,1 and3. The driver verifies them, then replaces/appends/truncates each of data/publickey/signature and adds missing/empty/malformed values.',
 'Why are a wrong supplied public key and a corrupted message handled through different response paths?')
update('txn/txnlock.md','Provide a process-global advisory transaction-building lock.',
 ['lockFunction synchronizes access: enabling succeeds only when not already locked; disabling clears the flag and returns true.','getLock retries every100ms. Its counter is increased after each sleep; a nonzero timeout fails only when counter>timeout. Timeout0 waits indefinitely.','runCommand reads action, timeout and unlockdelay before branching. lock returns success plus locked:true even when acquisition failed; list reports the actual global flag.','unlock waits for unlockdelay before clearing the lock, despite help text suggesting an after-unlock delay. A negative delay fails before unlocking.'],
 'C++ combines a mutex for lockFunction with an atomic observable flag, explicit counter wraparound and bounded sleep chunks for large delays. Java interruption semantics and arbitrary concurrent caller behavior remain incomplete.',
 'The driver performs lock/list/retry/unlock sequences with short and negative timeouts, a100ms boundary, negative/positive unlock delays and malformed values for every parameter. Calls share process-global lock state. This is not a comprehensive fairness/concurrent stress proof.',
 'If acquisition times out, why does the reply still contain locked:true? Distinguish that literal response field from successful ownership.')
print('Authored14command lessons.')
